class Solution {
    public int[] sortArray(int[] nums) {
        quick(nums, 0, nums.length - 1);
        return nums;
    }

    // 把 nums[l..r] 排好
    private void quick(int[] nums, int l, int r) {
        if (l >= r) {                           // 只剩 0 或 1 个数
            return;
        }
        int pivot = nums[l + (r - l) / 2];      // 取中间的数当基准
        int i = l - 1, j = r + 1;
        while (i < j) {
            do {
                i++;                            // 左边找一个 >= pivot 的
            } while (nums[i] < pivot);
            do {
                j--;                            // 右边找一个 <= pivot 的
            } while (nums[j] > pivot);
            if (i < j) {
                int t = nums[i];                // 交换以后两边都对了
                nums[i] = nums[j];
                nums[j] = t;
            }
        }
        quick(nums, l, j);                      // [l, j] 都 <= pivot
        quick(nums, j + 1, r);                  // [j+1, r] 都 >= pivot
    }
}

