class Solution {
    public int findKthLargest(int[] nums, int k) {
        int target = nums.length - k;           // 第 k 大 = 从小到大排好后下标 n-k 的数
        int l = 0, r = nums.length - 1;
        while (l < r) {
            int pivot = nums[l + (r - l) / 2];
            int i = l - 1, j = r + 1;
            while (i < j) {
                do {
                    i++;
                } while (nums[i] < pivot);
                do {
                    j--;
                } while (nums[j] > pivot);
                if (i < j) {
                    int t = nums[i];
                    nums[i] = nums[j];
                    nums[j] = t;
                }
            }
            if (target <= j) {                  // 答案在左边一段
                r = j;
            } else {                            // 答案在右边一段
                l = j + 1;
            }
        }
        return nums[l];
    }
}

